INSERT INTO catalog_products (id,slug,name,base_price_usd,sale_price_usd,tags_json,image_url,image_card_url,is_hot,shop_order,short_description,description_json,release_year,developer,platform,is_active) VALUES ('md-19','codiguin-snicker','Codiguin Coelhão Snicker',3.2859,6.5717,'["migrado-md", "free-fire"]','/assets/catalog/freefire-pass-codes.jpg','/assets/catalog/freefire-pass-codes.jpg',0,1019,'Coelhão Snicker CODIGUIN MAIS BARATO DA PLATAFORMA!!','["🔐 COMPRA SEGURA\n✅ Código original e válido\n✅ Entrega rápida após confirmação do pagamento\n✅ Não é necessário fornecer login ou senha\n✅ Processo simples e transparente\n✅ Atendimento sério e profissional\n\n🛡 GARANTIA\n🔹 Código enviado corretamente para ativação\n🔹 Total segurança na negociação\n🔹 Clareza em todas as etapas da compra\n🔹 Compromisso e responsabilidade com cada cliente\n\n📦 COMO FUNCIONA\n1️⃣ Realize o pagamento\n2️⃣ Receba seu código exclusivo\n3️⃣ Acesse o site oficial:\n👉 https://reward.ff.garena.com/en�\n4️⃣ Faça login na sua conta\n5️⃣ Insira o código no campo indicado e confirme\n\n🎁 Após a confirmação, os itens serão enviados diretamente para sua conta no jogo."]',2026,'GameAO','Free Fire',1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,base_price_usd=EXCLUDED.base_price_usd,sale_price_usd=EXCLUDED.sale_price_usd,tags_json=EXCLUDED.tags_json,image_url=EXCLUDED.image_url,image_card_url=EXCLUDED.image_card_url,is_hot=EXCLUDED.is_hot,short_description=EXCLUDED.short_description,description_json=EXCLUDED.description_json,platform=EXCLUDED.platform,is_active=1;
