INSERT INTO catalog_products (id,slug,name,base_price_usd,sale_price_usd,tags_json,image_url,image_card_url,is_hot,shop_order,short_description,description_json,release_year,developer,platform,is_active) VALUES ('md-23','psvita','PSVITA',81.0515,94.1950,'["migrado-md", "playstation"]','/assets/catalog/freefire-catalog.jpg','/assets/catalog/freefire-catalog.jpg',0,1023,'Transforma qualquer lugar na tua própria sala de jogos com a PlayStation Vita, agora disponível na GameAO.','["Já entregamos a consola totalmente desbloqueada, o que a converte na derradeira máquina de entretenimento portátil. O que isto significa para ti? Que não ficas limitado apenas aos jogos originais. Terás a liberdade de explorar uma biblioteca gigante que inclui:\n\nJogos nativos da PS Vita com gráficos incríveis.\n\nTodo o catálogo da PSP e clássicos da PS1 para uma verdadeira viagem no tempo.\n\nMilhares de jogos retro através de emuladores (Super Nintendo, Game Boy, Sega, etc.).\n\nCom os seus dois analógicos precisos e um ecrã vibrante, a PS Vita oferece uma experiência de jogo real que os telemóveis não conseguem igualar. Esquece os tutoriais e as instalações complicadas — a nossa equipa da GameAO já fez o trabalho difícil por ti. A consola está pronta a usar. Visita-nos e eleva a tua diversão para o próximo nível!"]',2026,'GameAO','PlayStation',1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,base_price_usd=EXCLUDED.base_price_usd,sale_price_usd=EXCLUDED.sale_price_usd,tags_json=EXCLUDED.tags_json,image_url=EXCLUDED.image_url,image_card_url=EXCLUDED.image_card_url,is_hot=EXCLUDED.is_hot,short_description=EXCLUDED.short_description,description_json=EXCLUDED.description_json,platform=EXCLUDED.platform,is_active=1;
INSERT INTO catalog_products (id,slug,name,base_price_usd,sale_price_usd,tags_json,image_url,image_card_url,is_hot,shop_order,short_description,description_json,release_year,developer,platform,is_active) VALUES ('md-24','desbloqueio-psvita','DESBLOQUEIO PSVITA',27.3823,35.0493,'["migrado-md", "playstation"]','/assets/catalog/freefire-catalog.jpg','/assets/catalog/freefire-catalog.jpg',0,1024,'Transforma a tua velha PlayStation Vita na derradeira máquina de jogos com o serviço de desbloqueio especializado da GameAO! Se tens a consola esquecida na gaveta por causa do preço dos jogos físicos, nós temos a solução perfeita.','["Com o nosso serviço, a tua consola fica totalmente livre de limitações. Para garantirmos que sais da nossa loja a jogar, oferecemos a instalação de 5 jogos à tua escolha logo no momento do desbloqueio.\n\nAo fazeres o desbloqueio connosco, ganhas acesso a:\n\nOferta Imediata: 5 jogos instalados pela nossa equipa, prontos a abrir e jogar.\n\nCatálogo Infinito: Acesso a uma loja virtual instalada na consola com mais de 6.000 opções de jogos totalmente desbloqueados.\n\nVariedade Máxima: Possibilidade de descarregar os melhores títulos da PS Vita, todo o catálogo da PSP, clássicos inesquecíveis da PS1 e centenas de jogos retro através de emuladores.\n\nO processo é seguro, rápido e garantido pela nossa equipa. Traz a tua PS Vita à GameAO, escolhe os teus 5 jogos de oferta e descobre um mundo com milhares de aventuras à tua espera!"]',2026,'GameAO','PlayStation',1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,base_price_usd=EXCLUDED.base_price_usd,sale_price_usd=EXCLUDED.sale_price_usd,tags_json=EXCLUDED.tags_json,image_url=EXCLUDED.image_url,image_card_url=EXCLUDED.image_card_url,is_hot=EXCLUDED.is_hot,short_description=EXCLUDED.short_description,description_json=EXCLUDED.description_json,platform=EXCLUDED.platform,is_active=1;
INSERT INTO catalog_products (id,slug,name,base_price_usd,sale_price_usd,tags_json,image_url,image_card_url,is_hot,shop_order,short_description,description_json,release_year,developer,platform,is_active) VALUES ('md-25','jogos-xbox','Jogos Xbox Mídia Parental Baratos - Xbox One/series Sx',5.0383,8.6528,'["migrado-md", "xbox"]','/assets/catalog/freefire-weapons.jpg','/assets/catalog/freefire-weapons.jpg',1,1025,'Escolha 1 Jogo na descrição completa','["🃏 Conta Parental – Xbox One e Series\n❌ Não funciona em PC, Xbox 360 ou xCloud\n\nAntes de efetuar a compra, é muito importante que o comprador saiba que será necessário aplicar corretamente o Método Parental para jogar. Caso ainda não conheça o método, recomendamos pesquisar previamente, ler toda a descrição com atenção ou entrar em contato para esclarecer qualquer dúvida antes da compra.\n\n📘 Tutorial Completo + Suporte\nApós a confirmação da compra, você receberá:\n• Acesso à conta com o jogo adquirido (30 dias)\n• Tutorial completo com passo a passo detalhado\n• Vídeos explicativos para facilitar o processo\n• Suporte total até o jogo estar funcionando corretamente no seu perfil pessoal\n\n🎮 Lista de Jogos\nTemos muitos jogos disponíveis e a plataforma não permite exibir todos no anúncio.\n💰 Cada jogo por 4600kz na Promoção\n\nLISTA em Ordem Alfabética: 📈\n• Alan Wake 1\n• Alan Wake 2 Deluxe\n• Avatar Frontiers of Pandora\n• Assassins Creed Mirage\n• Assassins Creed Odyssey + (DLCS)\n• Assassins Creed Valhala + (DLCS)\n• Assassins Creed Trilogy\n• Assassins Creed Ezio Collection\n• Assassins Creed Rogue Remaster\n• Ark Survival Evolved\n• Baldurs Gate 3 + Batman Trilogy\n• Bully + Blashphemus\n• Battlefield 2024\n• Battlefield 1 + Battlefield V\n• Battlefield 4\n• Boderlands 2 + Boderlands 3\n• Boderlands 4\n• Bayonetta Remaster\n• Biomutant\n• Cars 2 - The vídeo game\n• Crash Bandicoot Trilogy + Crash 4\n• Call of Duty®: Black Ops 2\n• Call of Duty: Black Ops 4\n• Call of Duty Ghosts\n• Call of Duty WW2\n• Celeste\n• Cyberpunk 2077 Ultimate Edition\n• Dark Souls Remaster\n• Dark Souls 1 360\n• Dandara Trials of Fear\n• Devil May Cry 4 + DMC 5 + HD Collection + DMC Definitive Edition\n• Dragons Dogma 2 Deluxe\n• Dragon Age Inquisition\n• Dying Light 1 + 2 Stay Human\n• Dying Light The Beast\n• Dragon Ball Xenoverse 2 + DBZ Fightz\n• Dragon Ball Z Kakarot Deluxe\n• Diablo 4\n• Deaths Door\n• Dead Island 2 Deluxe + Doom Eternal\n• Esquadrão Suicida NOVO\n• EA FIFA 16\n• EA FIFA 20\n• EA FIFA 21\n• EA FIFA 22 Xbox One\n• EA FIFA 23 Xbox One e Series\n• EA FIFA 25 Xbox One e Series\n• EA Madden NFL 25 + College Football 25\n• Far Cry 3,4,5 e 6\n• FNAF 1-4\n• F124\n• F125\n• Forza Horizon 1\n• Final Fantasy 16 Ultimate\n• Gears 5 Ultimate Edition + Gears 4\n• Gotham Knights + Guardiões Da Galaxia\n• Ghost Recon Breakpoint + Wildlands\n• GTA Trilogia\n• Hades\n• High On Life\n• Hollow Knight Silksong\n• Hotline Miami 1 e 2\n• Injustice 2\n• Inazuma Eleven Victory Road\n• Immortal Fênix Rising\n• Jump Force\n• Judgment\n• Jojo All Star Battle R\n• Kingdom Come Deliverance 2 e 1\n• Lego Indiana Jones 1, 2\n• Lego Batman 2\n• LEGO® Star Wars™: The Skywalker Saga\n• LEGO® Marvel Super Heroes 1\n• LEGO® Marvel Super Heroes 2 Deluxe\n• LEGO® Marvel Vingadores\n• LEGO Batman 3 Além de Gotham\n• LEGO DC Vilanns\n• Like a Dragon Infinite Wealth\n• Mortal Kombat 11 Ultimate\n• Marvel Vs Capcom infinite\n• Máfia Trilogy\n• Máfia Old Country\n• Metal Gear 3 Remake\n• Metaphor ReFantazio\n• Mad Max\n• Maneater Apexx Edition\n• Marvel Ultimate Aliance Bundle 1 2\n• Madden NFL 15 e 17\n• Monster Hunter World\n• Monster Hunter Wilds DELUXE\n• Mouse Pi For Hire\n• Naruto Ultimate Ninja Storm 4\n• NBA 2K25\n• NBA 2K17 + 2K18 + 2K20 + 2K22\n• Need For Speed Heat + Payback\n• Nightmares Complete Edition\n• Nier Automata + Nier Replicant\n• No mans SKY\n• No Time To Relax\n• Ori And The Blind Forest\n• One Piece Pirate Warriors 4\n• ON THE ROAD - The Truck Simulator\n• Outlast Bundle 1 e 2\n• PES 2020\n• Punc Club 1 e 2\n• Riders Republic Gold\n• Resident Evil 7 + DLCS\n• Resident Vilagge + DLC\n• Rayman Legends\n• Resident 2 Deluxe\n• Ready Or Not\n• Shadow Of Tomb Raider Deluxe\n• Stardew Valley\n• Super Bomberman R\n• Street Fighter 6\n• Sonic All-Stars Racing Transformed\n• Star Wars Jedi Falen Order Deluxe\n• Star Wars Jedi Survivor Deluxe\n• South Park The Stick OF Truth\n• South Park A Fenda que Abunda Força\n• The Crew 2 + Shadow of War\n• The Division 2\n• The Outlast Trials\n• Tekken 7\n• Tekken 8\n• The King OF Fightrs XV\n• Tony Hawks Pro Skater 1 + 2\n• The Witcher 3 Complete Edition\n• The Elder Scrolls V\n• The Binding Of Isaac Rebirth\n• UFC 1 - 2014 + Yakuza Like a Dragon\n• UFC 5\nDemais jogos pergunta pelo suporte ou no Whatsapp.\n\n🎁 BÔNUS EXCLUSIVO\nNa compra, você ainda leva de presente um destes jogos à sua escolha 👇\n•Pacote Crash Bandicoot™ N. Sane Trilogy + CTR Nitro-Fueled, DEATH STRANDING, AC Mirage, Farming Simulator 25, Mafia: Trilogy, NBA2K25, F124, DARK SOULS REMASTER,\n\n• Garantia e Suporte\nOferecemos suporte e acesso de funcionamento total do nosso produto durante 30 dias. Tempo esse pré estabelecido de acordo com os termos do site."]',2026,'GameAO','Xbox',1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,base_price_usd=EXCLUDED.base_price_usd,sale_price_usd=EXCLUDED.sale_price_usd,tags_json=EXCLUDED.tags_json,image_url=EXCLUDED.image_url,image_card_url=EXCLUDED.image_card_url,is_hot=EXCLUDED.is_hot,short_description=EXCLUDED.short_description,description_json=EXCLUDED.description_json,platform=EXCLUDED.platform,is_active=1;
INSERT INTO catalog_products (id,slug,name,base_price_usd,sale_price_usd,tags_json,image_url,image_card_url,is_hot,shop_order,short_description,description_json,release_year,developer,platform,is_active) VALUES ('md-26','fc-26-ps4-ps5','EA SPORTS FC™ 26 | PS4 / PS5 (Mídia Digital)',18.6199,40.1972,'["migrado-md", "playstation"]','/assets/catalog/freefire-catalog.jpg','/assets/catalog/freefire-catalog.jpg',0,1026,'EA SPORTS FC™ 26 para PS4/PS5 em mídia digital. Receba seu jogo rapidamente, com ativação segura e suporte completo na instalação. Jogue a nova geração do futebol com mais realismo, gráficos incríveis e modos online.','["⚽ EA SPORTS FC™ 26 | PS4 / PS5 (Mídia Digital)\n\nViva uma experiência de futebol mais realista, intensa e emocionante com o EA SPORTS FC™ 26.\n\nReceba seu jogo em mídia digital, sem precisar de disco físico, com entrega rápida e todo o suporte necessário para começar a jogar.\n\n✅ O que está incluso\n\n* 🎮 EA SPORTS FC™ 26\n* 🕹️ Compatível com PS4 e PS5\n* 💾 Mídia Digital (não é disco)\n* 🔐 Ativação segura\n* ⚡ Envio rápido\n* 🛠️ Suporte completo para instalação\n* ✔️ Produto 100% original\n\n📦 Como funciona?\n\nApós a confirmação do pagamento, nossa equipe enviará as instruções para ativação do jogo. Caso tenha qualquer dificuldade, oferecemos suporte durante todo o processo de instalação.\n\n💡 Por que comprar na GameAO?\n\n* Compra segura\n* Atendimento rápido\n* Suporte especializado\n* Entrega ágil\n* Clientes satisfeitos em todo o país\n\nImportante: Este produto é uma mídia digital. Não acompanha disco físico nem caixa. Verifique a descrição da oferta antes da compra para confirmar a modalidade de ativação disponível."]',2026,'GameAO','PlayStation',1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,base_price_usd=EXCLUDED.base_price_usd,sale_price_usd=EXCLUDED.sale_price_usd,tags_json=EXCLUDED.tags_json,image_url=EXCLUDED.image_url,image_card_url=EXCLUDED.image_card_url,is_hot=EXCLUDED.is_hot,short_description=EXCLUDED.short_description,description_json=EXCLUDED.description_json,platform=EXCLUDED.platform,is_active=1;
INSERT INTO catalog_products (id,slug,name,base_price_usd,sale_price_usd,tags_json,image_url,image_card_url,is_hot,shop_order,short_description,description_json,release_year,developer,platform,is_active) VALUES ('md-27','call-of-duty-modern-warfare','Call of Duty: Modern Warfare | PS4 / PS5 (Mídia Digital)',15.3341,24.0964,'["migrado-md", "playstation"]','/assets/catalog/freefire-catalog.jpg','/assets/catalog/freefire-catalog.jpg',0,1027,'Entre no campo de batalha com Call of Duty: Modern Warfare para PS4/PS5 em mídia digital. Receba seu jogo rapidamente, com ativação segura e suporte completo na instalação.','["Prepare-se para uma campanha intensa, combates táticos e uma experiência de tiro de alto nível em Call of Duty: Modern Warfare.\n\nJogue um dos FPS mais aclamados da franquia, com gráficos impressionantes, modos multiplayer eletrizantes e missões cheias de ação.\n\n✅ O que está incluso\n\n* 🎮 Call of Duty: Modern Warfare\n* 🕹️ Compatível com PS4 e PS5\n* 💾 Mídia Digital (não é disco)\n* 🔐 Ativação segura\n* ⚡ Envio rápido\n* 🛠️ Suporte completo para instalação\n* ✔️ Produto 100% original\n\n📦 Como funciona?\n\nApós a confirmação do pagamento, você receberá todas as instruções para ativação do jogo. Nossa equipe acompanha todo o processo caso precise de ajuda.\n\n💥 Por que comprar na GameAO?\n\n* Compra segura\n* Entrega rápida\n* Atendimento especializado\n* Suporte do início ao fim\n* Produto digital original\n\nImportante: Este produto é uma mídia digital. Não acompanha disco físico."]',2026,'GameAO','PlayStation',1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,base_price_usd=EXCLUDED.base_price_usd,sale_price_usd=EXCLUDED.sale_price_usd,tags_json=EXCLUDED.tags_json,image_url=EXCLUDED.image_url,image_card_url=EXCLUDED.image_card_url,is_hot=EXCLUDED.is_hot,short_description=EXCLUDED.short_description,description_json=EXCLUDED.description_json,platform=EXCLUDED.platform,is_active=1;
INSERT INTO catalog_products (id,slug,name,base_price_usd,sale_price_usd,tags_json,image_url,image_card_url,is_hot,shop_order,short_description,description_json,release_year,developer,platform,is_active) VALUES ('md-28','god-of-war-ps4-ps5','God of War | PS4 / PS5 (Mídia Digital)',24.0964,30.1205,'["migrado-md", "playstation"]','/assets/catalog/freefire-catalog.jpg','/assets/catalog/freefire-catalog.jpg',0,1028,'Viva a jornada épica de Kratos e Atreus em God of War para PS4/PS5. Mídia digital, entrega rápida e suporte completo para instalação.','["⚔️ God of War | PS4 / PS5 (Mídia Digital)\n\nEmbarque em uma aventura inesquecível ao lado de Kratos e Atreus, explorando os reinos da mitologia nórdica em um dos jogos mais premiados da história.\n\nCom combates intensos, gráficos incríveis e uma narrativa emocionante, God of War oferece uma experiência que todo jogador precisa viver.\n\n✅ O que está incluso\n\n* 🎮 God of War\n* 🕹️ Compatível com PS4 e PS5\n* 💾 Mídia Digital (não é disco)\n* 🔐 Ativação segura\n* ⚡ Envio rápido\n* 🛠️ Suporte completo para instalação\n* ✔️ Produto 100% original\n\n📦 Como funciona?\n\nApós a confirmação do pagamento, nossa equipe enviará as instruções para ativação do jogo. Caso precise, oferecemos suporte completo durante a instalação.\n\n🛡️ Por que comprar na GameAO?\n\n* Compra segura\n* Entrega rápida\n* Atendimento de qualidade\n* Suporte especializado\n* Produto digital original\n\nImportante: Este produto é uma mídia digital. Não acompanha disco físico."]',2026,'GameAO','PlayStation',1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,base_price_usd=EXCLUDED.base_price_usd,sale_price_usd=EXCLUDED.sale_price_usd,tags_json=EXCLUDED.tags_json,image_url=EXCLUDED.image_url,image_card_url=EXCLUDED.image_card_url,is_hot=EXCLUDED.is_hot,short_description=EXCLUDED.short_description,description_json=EXCLUDED.description_json,platform=EXCLUDED.platform,is_active=1;
INSERT INTO catalog_products (id,slug,name,base_price_usd,sale_price_usd,tags_json,image_url,image_card_url,is_hot,shop_order,short_description,description_json,release_year,developer,platform,is_active) VALUES ('md-30','jogos-digital-ps4ps5','JOGOS PARA A PS4/PS5',5.0383,NULL,'["migrado-md", "playstation"]','/assets/catalog/freefire-catalog.jpg','/assets/catalog/freefire-catalog.jpg',1,1030,'🎮 Jogo Digital PS4/PS5 – Versão Primária ou Secundária Receba os dados da conta diretamente no seu chat e jogue com total praticidade e segurança! ✅ Jogo original e completo ✅ Jogue na sua conta (Primária) ou no perfil enviado (Secundária) ✅ Versão de Ps4 funciona em ambos (Ps4 ou Ps5) ✅ Suporte e completo, durante a compra 30 dias de acesso após a entrega, com auxílio na instalação e esclarecimento de dúvidas.','["🎮 JOGOS DIGITAIS PS4/PS5 – VERSÃO PRIMÁRIA OU SECUNDÁRIA\n\nEscolha entre dezenas de jogos para PlayStation 4 e PlayStation 5 com entrega rápida, suporte dedicado e total segurança.\n\nApós a compra, basta selecionar o jogo desejado na lista de opções e concluir o pedido.\n\n✅ O que você recebe\n\n✔ Produto 100% Digital\n✔ Entrega rápida após confirmação do pagamento\n✔ Dados enviados diretamente pelo chat ou e-mail\n✔ Suporte antes, durante e após a compra\n✔ Instalação simples com instruções completas\n\n🎮 Escolha entre vários jogos\n\nEste anúncio reúne diversos títulos em um único produto.\n\nAlguns exemplos disponíveis:\n\n• EA Sports FC 26\n• Call of Duty\n• GTA V\n• God of War\n• Ghost of Yotei\n• Resident Evil\n• Dragon Ball\n• FIFA\n• NBA 2K\n• Spider-Man\n• Hogwarts Legacy\n• Cyberpunk 2077\n• Elden Ring\n\n...e muitos outros.\n\nA lista é atualizada constantemente.\n\n🔹 Versão Primária\n\nIdeal para quem deseja jogar utilizando sua própria conta PlayStation.\n\n✅ Jogue normalmente no seu perfil principal.\n\n🔹 Versão Secundária\n\nExcelente opção para economizar.\n\nApós a instalação, basta seguir as instruções enviadas junto ao produto.\n\n📦 Como funciona\nEscolha o jogo desejado.\nFinalize a compra.\nAguarde a confirmação do pagamento.\nReceba os dados da conta rapidamente.\nSiga o guia de instalação.\nAproveite seu jogo.\n⚡ Entrega\n\nApós a confirmação do pagamento, o envio normalmente ocorre em poucos minutos durante o horário de atendimento.\n\nEm períodos de grande movimento poderá haver pequeno tempo adicional.\n\n🛡️ Compra Segura\n\n✔ Atendimento rápido\n✔ Suporte especializado\n✔ Produto testado antes da entrega\n✔ Centenas de clientes atendidos\n✔ Processo simples e seguro\n\n❗ Importante\n\n• Leia atentamente a descrição antes de comprar.\n• Escolha corretamente o jogo e a versão desejada (Primária ou Secundária).\n• Produtos digitais não possuem frete.\n• Após a entrega dos dados da conta, não é possível realizar trocas por outro jogo, exceto em caso de defeito no produto enviado.\n• Não altere os dados da conta fornecida.\n\n💬 Dúvidas?\n\nCaso tenha qualquer dúvida sobre compatibilidade, versão ou disponibilidade de algum jogo, entre em contato antes da compra. Nossa equipe terá prazer em ajudar.\n\n🎮 Escolha seu jogo, conclua a compra e comece a jogar hoje mesmo!"]',2026,'GameAO','PlayStation',1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,base_price_usd=EXCLUDED.base_price_usd,sale_price_usd=EXCLUDED.sale_price_usd,tags_json=EXCLUDED.tags_json,image_url=EXCLUDED.image_url,image_card_url=EXCLUDED.image_card_url,is_hot=EXCLUDED.is_hot,short_description=EXCLUDED.short_description,description_json=EXCLUDED.description_json,platform=EXCLUDED.platform,is_active=1;
