RE\n✅1 TROCA NICK\n✅NIVEL 5-(VIA GMAIL)\n\nAPENAS 2.000 KZ\n\nAPÓS O PAGAMENTO, VOCE RECEBERA EMAIL E SENHA QUE PODERAM SER ALTERADOS.\n\nALGUMA DUVIDA, CHAME NO NOSSO WHATSAPP."]',2026,'GameAO','Free Fire',1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,base_price_usd=EXCLUDED.base_price_usd,sale_price_usd=EXCLUDED.sale_price_usd,tags_json=EXCLUDED.tags_json,image_url=EXCLUDED.image_url,image_card_url=EXCLUDED.image_card_url,is_hot=EXCLUDED.is_hot,short_description=EXCLUDED.short_description,description_json=EXCLUDED.description_json,platform=EXCLUDED.platform,is_active=1;
