INSERT INTO catalog_products (id,slug,name,base_price_usd,sale_price_usd,tags_json,image_url,image_card_url,is_hot,shop_order,short_description,description_json,release_year,developer,platform,is_active) VALUES ('md-33','robux','MOEDAS ROBUX - ROBLOX',1.5334,NULL,'["migrado-md", "roblox"]','/assets/catalog/freefire-diamonds.jpg','/assets/catalog/freefire-diamonds.jpg',1,1033,'NAO PRECISAMOS DO ACESSO DA SUA CONTA, APENAS O USUARIO PARA ENVIAR OS ROBUX.','["‼️LEIA AS INFORMAÇÕES IMPORTANTES‼️\n\nRobux é a moeda virtual que pode ser comprada usando sua moeda local ou com créditos do cartão presente Roblox. Ela permite que os usuários personalizem seu avatar e comprem habilidades e itens especiais em experiências.\n\nCOMO VOU RECEBER MEUS ROBUX❓\n- EU IREI TE ENVIAR OS ROBUX PELO MEIO DA ASSINATURA (ROBLOX PLUS).\n- QUANDO EU TE ENVIAR E SO VOCE CLICAR EM ACEITAR.\n\n⚠️UMA VEZ QUE OS ROBUX SEJAM ENVIADOS DIRETAMENTE PARA VOCE, ELES NAO PODEM SER REEMBOLSADOS PARA MIM (VAI FICAR NA SUA CONTA ATE VOCE ACEITAR ELES).\n\nQUANTO TEMPO ELE DEMORA PARA CAIR❓\n- ELE CAI INSTANTANEAMENTE OU SEJA NA HORA. (QUANDO VOCE ACEITAR‼️)\n\nOS ROBUX ENVIADOS TEM TAXA❓\n- NAO, ELES NAO TEM TAXA, ELES CAEM LIMPINHO DO MESMO VALOR QUE VOCE COMPROU💲\n\n‼️MUITO IMPORTANTE (LEIAM COM ATENCAO)‼️\n- CASO SUA CONTA DO ROBLOX SEJA VERIFICADA COMO -16 ANOS, VOCE TERA QUE TER A PERMISSAO DO SEU RESPONSAVEL, VEJA O PASSO A PASSO AQUI EM BAIXO‼️\n\n1 - LOGO APOS O ENVIO DOS ROBUX, VOCE PRECISA ACEITAR, MAS...\n2 - NA SUA TELA VOCE TERA QUE COLOCAR O EMAIL DO SEU RESPONSAVEL.\n3 - APOS ISSO, O ROBLOX VAI ENVIAR UM EMAIL PARA O SEU RESPONSAVEL COM AS INFORMACOES PARA ACEITAR O ROBUX PARA VOCE.\n4 - NISSO O SEU RESPONSÁVEL TERA QUE CRIAR UMA CONTA DO ROBLOX, ADICIONAR EMAIL, VERIFICAR ELA E TALS..."]',2026,'GameAO','Roblox',1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,base_price_usd=EXCLUDED.base_price_usd,sale_price_usd=EXCLUDED.sale_price_usd,tags_json=EXCLUDED.tags_json,image_url=EXCLUDED.image_url,image_card_url=EXCLUDED.image_card_url,is_hot=EXCLUDED.is_hot,short_description=EXCLUDED.short_description,description_json=EXCLUDED.description_json,platform=EXCLUDED.platform,is_active=1;
