INSERT INTO catalog_products (id,slug,name,base_price_usd,sale_price_usd,tags_json,image_url,image_card_url,is_hot,shop_order,short_description,description_json,release_year,developer,platform,is_active) VALUES ('md-34','robux-gif-card','Robux Gif Card',11.3910,NULL,'["migrado-md", "roblox"]','/assets/catalog/freefire-diamonds.jpg','/assets/catalog/freefire-diamonds.jpg',1,1034,'+25% resgatando pelo navegador','["Resgatável somente para contas correspondente ao Brasil.\n\nOs códigos são novos e nunca utilizados, passados diretamente no chat ao comprador.\n\nSeu saldo não poderá ser cancelado, trocado, devolvido ou ser convertido em dinheiro.\n\nTenha responsabilidade ao ativar o seu código.\n\nComo resgatar?\n\n1 - Acesse a página https://www.roblox.com/redeem \n2 - Copie e Cole o código PIN informado acima e clique em resgatar.\n3 - Na mesma página converta o saldo para Robux até que fique zerado.\n\n🚨 Até 25% de Bônus além do valor do anúncio caso resgatado em um navegador de internet ao invés de dentro do jogo."]',2026,'GameAO','Roblox',1) ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,base_price_usd=EXCLUDED.base_price_usd,sale_price_usd=EXCLUDED.sale_price_usd,tags_json=EXCLUDED.tags_json,image_url=EXCLUDED.image_url,image_card_url=EXCLUDED.image_card_url,is_hot=EXCLUDED.is_hot,short_description=EXCLUDED.short_description,description_json=EXCLUDED.description_json,platform=EXCLUDED.platform,is_active=1;
